// app-level engine assembly — in your app's composition root (e.g. apps/api/src/wiring/)
import { createScopedAc } from "@prowd/scoped-ac";
import { createScopeMiddleware } from "@prowd/scoped-ac/adapters/hono";
import { eq, ne, and, or, not, inArray, sql } from "drizzle-orm";
import * as schema from "@/models";
import { roles, hierarchy, subjects } from "@configs/access-control";
import { createBuildScopeContext } from "@prowd/user-organization-mgmt/api";
import { db } from "@/lib/db";

const moduleEntitySchema = {
  organization: { table: schema.organization, metadata: schema.organization.metadata },
  member:       { table: schema.member },
  invitation:   { table: schema.invitation },
  // …one entry per entity referenced in any rule
};

export const engine = createScopedAc({
  roles,
  hierarchy,
  subjects,
  schema: moduleEntitySchema,
  sql: { eq, ne, and, or, not, inArray, sql },
});

export const ac = {
  engine,
  middleware: createScopeMiddleware({
    engine,
    buildContext: createBuildScopeContext({ db }),
  }),
};

interface ScopedAc {
  expandRoles(assignedRoles: string[]): string[];

  resolveRead   (effective, entity, subjects):              ResolvedScope;   // { where, select, joins }
  resolveUpdate (effective, entity, subjects):              ResolvedScope;
  resolveCreate (effective, entity, subjects, properties):  ScopeVerdict;    // { allow, reason? }
  resolveDelete (effective, entity, subjects, properties):  ScopeVerdict;

  explainScopeResolution(role, ctx): ScopeExplanation;

  readonly roles, hierarchy, schema, subjects;
}

interface ScopedAcRequestContext {
  subjects;
  assignedRoles;
  effectiveRoles;
  resolveRead   (entity):         ResolvedScope;
  resolveUpdate (entity):         ResolvedScope;
  resolveCreate (entity, props):  ScopeVerdict;
  resolveDelete (entity, props):  ScopeVerdict;
  explainScopeResolution(role):   ScopeExplanation;
}
